// --- KEYWORD-BASED MATCHING WITH FIXED DATE EXTRACTION ---

const items = $input.all();
const results = [];
let queryItem = null;

const eventItems = items.filter(item => {
    if (item.json.row_number) {
        return true;
    }
    if (item.json.queryQuestion || item.json.question) {
        queryItem = item.json;
    }
    return false;
});

if (!queryItem) {
    return [{ json: { error: 'Query data missing' } }];
}

const queryQuestion = queryItem.queryQuestion || queryItem.question || '';
const queryLanguage = queryItem.language || "English";
const intent = queryItem.intent || '';

console.log('=== QUERY DEBUG ===');
console.log('Query:', queryQuestion);

// Extract keywords helper
function extractKeywords(value) {
    if (!value) return [];
    return value.toString()
        .toLowerCase()
        .split(',')
        .map(k => k.trim())
        .filter(k => k.length >= 2);
}

// Get keywords from query item
let categoryKeywords = [];
let dateKeywords = [];

if (queryItem.eventKeywords) {
    categoryKeywords = extractKeywords(queryItem.eventKeywords);
}
if (queryItem.dateTimeKeywords) {
    dateKeywords = extractKeywords(queryItem.dateTimeKeywords);
}

console.log('Category Keywords:', categoryKeywords);
console.log('Date Keywords:', dateKeywords);

// SIMPLE DATE EXTRACTION (WORKING VERSION)
function extractDateSimple(query) {
    const q = query.toLowerCase().replace(/[.?!,]/g, ' ').trim();
    console.log('Cleaned query for date:', q);

    let day = null;
    const dayPatterns = [
        /\b1st\b/, /\b2nd\b/, /\b3rd\b/, /\b4th\b/, /\b5th\b/,
        /\b6th\b/, /\b7th\b/, /\b8th\b/, /\b9th\b/, /\b10th\b/,
        /\b11th\b/, /\b12th\b/, /\b13th\b/, /\b14th\b/, /\b15th\b/,
        /\b16th\b/, /\b17th\b/, /\b18th\b/, /\b19th\b/, /\b20th\b/,
        /\b21st\b/, /\b22nd\b/, /\b23rd\b/, /\b24th\b/, /\b25th\b/,
        /\b26th\b/, /\b27th\b/, /\b28th\b/, /\b29th\b/, /\b30th\b/, /\b31st\b/
    ];

    for (let i = 0; i < dayPatterns.length; i++) {
        if (dayPatterns[i].test(q)) {
            day = i + 1;
            console.log('Found day:', day);
            break;
        }
    }

    if (!day) {
        const numMatch = q.match(/\b(\d{1,2})\b/);
        if (numMatch) {
            const num = parseInt(numMatch[1]);
            if (num >= 1 && num <= 31) {
                day = num;
                console.log('Found day (plain):', day);
            }
        }
    }

    let month = null;
    if (q.includes('nov') || q.includes('नवम्बर') || q.includes('नवंबर')) {
        month = 10;
        console.log('Found month: November');
    } else if (q.includes('dec') || q.includes('दिसम्बर') || q.includes('दिसंबर')) {
        month = 11;
        console.log('Found month: December');
    }

    if (day !== null && month !== null) {
        const date = new Date(2025, month, day);
        console.log('✅ DATE EXTRACTED:', date.toDateString());
        return date;
    }

    console.log('❌ No date in query');
    return null;
}

const queryDate = extractDateSimple(queryQuestion);

// Check date match
function matchesDate(queryDate, eventDate, eventDuration) {
    if (!queryDate || !eventDate) return false;

    const evtDate = new Date(eventDate);

    // EXACT DATE MATCH - Check this first
    if (queryDate.toDateString() === evtDate.toDateString()) {
        return true;
    }

    // MULTI-DAY RANGE EVENTS (e.g., "15 Nov - 5 Dec")
    if (eventDuration && eventDuration.includes(' - ')) {
        const rangeParts = eventDuration.toLowerCase().split(' - ');
        if (rangeParts.length === 2) {
            const startMatch = rangeParts[0].match(/(\d{1,2})\s*(nov|dec)/i);
            const endMatch = rangeParts[1].match(/(\d{1,2})\s*(nov|dec)/i);

            if (startMatch && endMatch) {
                const startDay = parseInt(startMatch[1]);
                const startMonth = startMatch[2].toLowerCase() === 'nov' ? 10 : 11;
                const endDay = parseInt(endMatch[1]);
                const endMonth = endMatch[2].toLowerCase() === 'nov' ? 10 : 11;

                const startDate = new Date(2025, startMonth, startDay);
                const endDate = new Date(2025, endMonth, endDay);

                return queryDate >= startDate && queryDate <= endDate;
            }
        }
    }

    // DAILY RECURRING EVENTS ONLY
    if (eventDuration === 'Daily') {
        const festStart = new Date(2025, 10, 15);
        const festEnd = new Date(2025, 11, 5);
        return queryDate >= festStart && queryDate <= festEnd;
    }

    // Single-day events (e.g., "1 Dec", "24 Nov") should NOT match other dates
    return false;
}

function normalizeText(text) {
    if (!text) return '';
    return text.toLowerCase().replace(/[.?!,🏃‍♂️]/g, '').trim();
}

// Extract query words
const stopWords = ['the', 'and', 'for', 'with', 'from', 'what', 'when', 'where', 'which', 'who', 'how', 'is', 'are', 'was', 'were', 'will', 'can', 'does', 'on', 'at', 'in'];
const queryWords = normalizeText(queryQuestion)
    .split(/\s+/)
    .filter(w => w.length >= 3 && !stopWords.includes(w));

// Combine all keywords
const allKeywords = [...new Set([...categoryKeywords, ...dateKeywords, ...queryWords])];

console.log('Final Search Keywords:', allKeywords);

// Score events
for (const item of eventItems) {
    const event = item.json;

    const eventNameEn = normalizeText(event.Event_Name_English || '');
    const eventNameHi = normalizeText(event.Event_Name_Hindi || '');
    const eventDescEn = normalizeText(event.Description_English || '');
    const eventDescHi = normalizeText(event.Description_Hindi || '');
    const eventCategory = normalizeText(event.Category || '');
    const eventVenueEn = normalizeText(event.Venue_English || '');
    const eventVenueHi = normalizeText(event.Venue_Hindi || '');
    const eventKeywordsEn = normalizeText(event.Keywords_English || '');
    const eventKeywordsHi = normalizeText(event.Keywords_Hindi || '');
    const eventDate = event.Date || '';
    const eventDuration = event.Duration || '';

    let matchCount = 0;
    const matchedKeywords = [];

    // DATE MATCHING - HIGHEST PRIORITY
    if (queryDate) {
        if (matchesDate(queryDate, eventDate, eventDuration)) {
            matchCount += 20;
            matchedKeywords.push(`DATE-MATCH (${queryDate.toLocaleDateString()})`);
            console.log('✅ DATE MATCH:', eventNameEn.substring(0, 50));
        }
    }

    // KEYWORD MATCHING
    for (const keyword of allKeywords) {
        if (!keyword || keyword.length < 3) continue;

        let keywordMatched = false;
        let whereMatched = '';

        // Event Name - HIGHEST priority
        if (eventNameEn.includes(keyword) || eventNameHi.includes(keyword)) {
            matchCount += 10;
            whereMatched = 'title';
            keywordMatched = true;
        }

        // Keywords fields - Very HIGH priority
        if (!keywordMatched && (eventKeywordsEn.includes(keyword) || eventKeywordsHi.includes(keyword))) {
            matchCount += 8;
            whereMatched = 'keywords';
            keywordMatched = true;
        }

        // Description
        if (!keywordMatched && (eventDescEn.includes(keyword) || eventDescHi.includes(keyword))) {
            matchCount += 5;
            whereMatched = 'description';
            keywordMatched = true;
        }

        // Venue
        if (!keywordMatched && (eventVenueEn.includes(keyword) || eventVenueHi.includes(keyword))) {
            matchCount += 4;
            whereMatched = 'venue';
            keywordMatched = true;
        }

        // Category
        if (!keywordMatched && eventCategory.includes(keyword)) {
            matchCount += 2;
            whereMatched = 'category';
            keywordMatched = true;
        }

        if (keywordMatched) {
            matchedKeywords.push(`${keyword} (${whereMatched})`);
        }
    }

    // THRESHOLD: Only include meaningful matches
// 🔧 FIX: For date queries, ONLY include events with DATE-MATCH
if (matchCount >= 8) {
    // NEW: Check if this is a date query
    const isDateQuery = queryDate !== null;
    const hasDateMatch = matchedKeywords.some(k => k.includes('DATE-MATCH'));

    // NEW: For date queries, SKIP events without date match
    if (isDateQuery && !hasDateMatch) {
        // Skip this event - wrong date!
        continue;
    }

    // Rest of code stays the same
    results.push({
        json: {
            ...event,
            "Event_Name": event.Event_Name_English || event.Event_Name,
            "queryQuestion": queryQuestion,
            "language": queryLanguage,
            "intent": intent,
            "source": 'IGM Events Database',
            "matchScore": matchCount,
            "matchedKeywords": matchedKeywords.join(', ')
        }
    });
}
}

console.log(`📊 Total matches: ${results.length}`);

if (results.length > 0) {
    results.sort((a, b) => b.json.matchScore - a.json.matchScore);

    const topScore = results[0].json.matchScore;
    console.log(`🏆 Top score: ${topScore}`);

    // For date queries, return ALL date matches
    if (queryDate) {
        const dateMatches = results.filter(r => 
            r.json.matchedKeywords && r.json.matchedKeywords.includes('DATE-MATCH')
        );

        if (dateMatches.length > 0) {
            console.log(`✅ Returning ${dateMatches.length} date matches`);
            return dateMatches;
        }
    }

    // For non-date queries, return top 5
    const scoreThreshold = Math.max(topScore - 5, 8);
    const topMatches = results.filter(r => r.json.matchScore >= scoreThreshold).slice(0, 10);

    console.log(`✅ Returning ${topMatches.length} top matches`);
    return topMatches;
}

return [{ json: { message: 'No events found', queryQuestion } }];

// --- Code for 4c. Filter Facilities (UPDATED FOR NEW DATABASE STRUCTURE) ---
// Uses Category_English/Category_Hindi and Keywords for better matching
// Supports all 7 facility types: Parking, Toilets, Water, Food Court, Refreshment Stall, Medical, ATM

const items = $input.all();
const results = [];

let queryItem = null;

// Separate facility data from query data
const facilityItems = items.filter(item => {
    // Check if this is facility data (has Category_English field)
    if (item.json.Category_English || item.json.Facility_ID) {
        return true;
    }
    // Check if this is query data
    if (item.json.facilityKeywords || item.json.queryQuestion) {
        queryItem = item.json;
    }
    return false;
});

// Validate we have query data
if (!queryItem || !queryItem.queryQuestion) {
    return [{ json: { error: 'Facility query data missing.' } }];
}

const queryQuestion = queryItem.queryQuestion;
const queryLanguage = queryItem.language || "English";
const facilityKeywords = queryItem.facilityKeywords || '';

console.log('=== FACILITY QUERY DEBUG ===');
console.log('Query:', queryQuestion);
console.log('Language:', queryLanguage);
console.log('Keywords:', facilityKeywords);
console.log('Total facility entries:', facilityItems.length);

// Normalize text function
function normalizeText(text) {
    if (!text) return '';
    return text.toLowerCase().replace(/\s+/g, ' ').trim();
}

// Extract query words (minimum 2 characters)
let queryWords = normalizeText(queryQuestion + ' ' + facilityKeywords)
    .split(/\s+/)
    .filter(w => w.length >= 2);

console.log('Query words:', queryWords.join(', '));

// Detect facility type from query - IMPROVED for short queries
const facilityTypeDetection = {
    parking: queryWords.some(w => w.includes('park') || w.includes('पार्क') || w.includes('car') || w.includes('vehicle') || w.includes('bike') || w.includes('bus') || w.includes('गाड़ी') || w.includes('वाहन')),
    toilets: queryWords.some(w => w.includes('toilet') || w.includes('washroom') || w.includes('restroom') || w.includes('bathroom') || w.includes('शौचालय') || w.includes('वॉशरूम') || w.includes('टॉयलेट')),
    water: queryWords.some(w => w.includes('water') || w.includes('drinking') || w.includes('paani') || w.includes('पानी') || w.includes('पीने')),
    food: queryWords.some(w => w.includes('food') || w.includes('eat') || w.includes('restaurant') || w.includes('meal') || w.includes('खा') || w.includes('भोजन') || w.includes('रेस्तरां')),
    refreshment: queryWords.some(w => w.includes('tea') || w.includes('coffee') || w.includes('snack') || w.includes('chai') || w.includes('refreshment') || w.includes('चाय') || w.includes('नाश्ता') || w.includes('स्नैक')),
    medical: queryWords.some(w => w.includes('medical') || w.includes('doctor') || w.includes('hospital') || w.includes('first') || w.includes('aid') || w.includes('चिकित्सा') || w.includes('डॉक्टर') || w.includes('अस्पताल')),
    atm: queryWords.some(w => w.includes('atm') || w.includes('cash') || w.includes('money') || w.includes('एटीएम') || w.includes('पैसे'))
};

// Detect location from query
const locationQuery = {
    brahmaSarovar: queryWords.some(w => ['brahma', 'sarovar', 'ब्रह्म', 'सरोवर'].includes(w)),
    north: queryWords.some(w => ['north', 'northern', 'उत्तर'].includes(w)),
    south: queryWords.some(w => ['south', 'southern', 'दक्षिण'].includes(w)),
    east: queryWords.some(w => ['east', 'eastern', 'पूर्व'].includes(w)),
    west: queryWords.some(w => ['west', 'western', 'पश्चिम'].includes(w)),
    railway: queryWords.some(w => ['railway', 'station', 'रेलवे', 'स्टेशन'].includes(w))
};

const isLocationQuery = locationQuery.brahmaSarovar || locationQuery.north || 
    locationQuery.south || locationQuery.east || locationQuery.west || locationQuery.railway;

console.log('Facility type detection:', facilityTypeDetection);
console.log('Location query:', locationQuery);

// Process each facility entry
for (const item of facilityItems) {
    const fac = item.json;

    // Get fields based on language
    const name = normalizeText(fac[`Name_${queryLanguage}`] || fac.Name_English || '');
    const category = normalizeText(fac.Category_English || '');
    const location = normalizeText(fac[`Location_${queryLanguage}`] || fac.Location_English || '');
    const keywords = normalizeText(fac[`Keywords_${queryLanguage}`] || fac.Keywords_English || '');
    const amenities = normalizeText(fac[`Amenities_${queryLanguage}`] || fac.Amenities_English || '');
    const capacity = normalizeText(fac[`Capacity_${queryLanguage}`] || fac.Capacity_English || '');

    let matchScore = 0;
    const matchedKeywords = [];

    // 1. CATEGORY MATCHING (Most important - 20 points)
    let categoryMatched = false;

    if (facilityTypeDetection.parking && category.includes('parking')) {
        matchScore += 20;
        matchedKeywords.push('Parking category');
        categoryMatched = true;
    }

    if (facilityTypeDetection.toilets && category.includes('toilet')) {
        matchScore += 20;
        matchedKeywords.push('Toilet category');
        categoryMatched = true;
    }

    if (facilityTypeDetection.water && category.includes('water')) {
        matchScore += 20;
        matchedKeywords.push('Water category');
        categoryMatched = true;
    }

    if (facilityTypeDetection.food && category.includes('food')) {
        matchScore += 20;
        matchedKeywords.push('Food category');
        categoryMatched = true;
    }

    if (facilityTypeDetection.refreshment && category.includes('refreshment')) {
        matchScore += 20;
        matchedKeywords.push('Refreshment category');
        categoryMatched = true;
    }

    if (facilityTypeDetection.medical && category.includes('medical')) {
        matchScore += 20;
        matchedKeywords.push('Medical category');
        categoryMatched = true;
    }

    if (facilityTypeDetection.atm && category.includes('atm')) {
        matchScore += 20;
        matchedKeywords.push('ATM category');
        categoryMatched = true;
    }

    // 2. KEYWORD MATCHING (High priority - 15 points max)
    if (keywords) {
        let keywordMatches = 0;
        for (const word of queryWords) {
            if (word.length < 2) continue;

            if (keywords.includes(word)) {
                keywordMatches++;
                matchedKeywords.push(`${word} (keyword)`);
            }
        }
        matchScore += Math.min(keywordMatches * 3, 15);
    }

    // 3. LOCATION MATCHING (10 points)
    if (isLocationQuery) {
        let locationMatched = false;

        if (locationQuery.brahmaSarovar && (location.includes('brahma') || location.includes('sarovar') || location.includes('ब्रह्म'))) {
            matchScore += 10;
            matchedKeywords.push('Near Brahma Sarovar');
            locationMatched = true;
        }

        if (locationQuery.north && location.includes('north')) {
            matchScore += 10;
            matchedKeywords.push('North side');
            locationMatched = true;
        }

        if (locationQuery.south && location.includes('south')) {
            matchScore += 10;
            matchedKeywords.push('South side');
            locationMatched = true;
        }

        if (locationQuery.east && location.includes('east')) {
            matchScore += 10;
            matchedKeywords.push('East side');
            locationMatched = true;
        }

        if (locationQuery.west && location.includes('west')) {
            matchScore += 10;
            matchedKeywords.push('West side');
            locationMatched = true;
        }

        if (locationQuery.railway && (location.includes('railway') || location.includes('station'))) {
            matchScore += 10;
            matchedKeywords.push('Near Railway Station');
            locationMatched = true;
        }
    }

    // 4. NAME MATCHING (5 points)
    let nameMatches = 0;
    for (const word of queryWords) {
        if (word.length < 3) continue;
        if (name.includes(word)) {
            nameMatches++;
            matchedKeywords.push(`${word} (name)`);
        }
    }
    if (nameMatches > 0) {
        matchScore += Math.min(nameMatches * 2, 5);
    }

    // 5. CAPACITY/AMENITIES MATCHING (Bonus 3 points)
    for (const word of queryWords) {
        if (word.length < 3) continue;
        if (capacity.includes(word) || amenities.includes(word)) {
            matchScore += 1;
        }
    }
    matchScore = Math.min(matchScore + 3, matchScore); // Cap bonus at 3

    // THRESHOLD: Minimum 5 points to be included (lowered for simple queries like "Parking?")
    if (matchScore >= 5) {
        results.push({
            json: {
                "Facility_ID": fac.Facility_ID,
                "Name_English": fac.Name_English,
                "Name_Hindi": fac.Name_Hindi,
                "Category_English": fac.Category_English,
                "Category_Hindi": fac.Category_Hindi,
                "Location_English": fac.Location_English,
                "Location_Hindi": fac.Location_Hindi,
                "Capacity_English": fac.Capacity_English,
                "Capacity_Hindi": fac.Capacity_Hindi,
                "Amenities_English": fac.Amenities_English,
                "Amenities_Hindi": fac.Amenities_Hindi,
                "Timing_English": fac.Timing_English,
                "Timing_Hindi": fac.Timing_Hindi,
                "Contact": fac.Contact,
                "Map_Link": fac.Map_Link,
                "Description_English": fac.Description_English,
                "Description_Hindi": fac.Description_Hindi,
                "queryQuestion": queryQuestion,
                "language": queryLanguage,
                "source": 'Facility',
                "matchScore": matchScore,
                "matchedKeywords": matchedKeywords.join(', ')
            }
        });
    }
}

// Sort by match score (highest first)
results.sort((a, b) => b.json.matchScore - a.json.matchScore);

console.log(`Found ${results.length} matching facilities`);

// Return results (limit to top 10 for better user experience)
if (results.length > 0) {
    console.log('Top 5 match scores:', results.slice(0, 5).map(r => r.json.matchScore));
    return results.slice(0, 10); // Return top 10 results
} else {
    // No matches found
    return [{
        json: {
            message: queryLanguage === 'Hindi' 
                ? 'कोई सुविधा नहीं मिली। कृपया पार्किंग, शौचालय, पानी, खाना आदि के बारे में पूछें।'
                : 'No facility found matching your query. Please ask about parking, toilets, water, food, etc.',
            searchedFor: queryQuestion,
            suggestion: queryLanguage === 'Hindi'
                ? 'पार्किंग, शौचालय, पीने का पानी, खाना, या चिकित्सा सुविधा के बारे में पूछें।'
                : 'Try asking about parking, toilets, drinking water, food, or medical facilities.',
            queryQuestion: queryQuestion,
            language: queryLanguage
        }
    }];
}

// --- Code for 5c. Compile Facility Answer (UPDATED - NO FOOTER) ---

const items = $input.all();

// Multilingual text templates (WITHOUT FOOTER)
const templates = {
    English: {
        notFound: "I couldn't find any facilities matching your query.",
        foundSingle: "🏢 Here is the facility for",
        foundMultiple: "🏢 I found {count} facilities for",
        location: "📍 Location",
        category: "🏷️ Type",
        capacity: "👥 Capacity",
        amenities: "✨ Amenities",
        contact: "📞 Contact",
        timing: "🕒 Timing",
        mapLink: "🗺️ Map",
        tryAgain: "Try asking about parking, toilets, drinking water, food, or medical facilities."
    },
    Hindi: {
        notFound: "मुझे कोई सुविधा नहीं मिली।",
        foundSingle: "🏢 यह सुविधा मिली",
        foundMultiple: "🏢 {count} सुविधाएं मिलीं",
        location: "📍 स्थान",
        category: "🏷️ प्रकार",
        capacity: "👥 क्षमता",
        amenities: "✨ सुविधाएं",
        contact: "📞 संपर्क",
        timing: "🕒 समय",
        mapLink: "🗺️ मैप",
        tryAgain: "पार्किंग, शौचालय, पीने का पानी, खाना, या चिकित्सा सुविधा के बारे में पूछें।"
    }
};

// Check if we have results
if (!items || items.length === 0) {
    return [{
        json: {
            response: templates.English.notFound,
            success: false
        }
    }];
}

// Check if it's an error or "no match" response
const firstItem = items[0].json;
const userQuestion = firstItem.queryQuestion || "your question";

if (firstItem.error || firstItem.message) {
    const lang = firstItem.language || "English";
    const t = templates[lang] || templates.English;

    return [{
        json: {
            response: firstItem.message || firstItem.error || t.notFound + "\n\n" + t.tryAgain,
            success: false,
            searchedFor: firstItem.searchedFor || "",
            suggestion: firstItem.suggestion || t.tryAgain,
            userQuestion: userQuestion
        }
    }];
}

// Get the user's question and language
const language = firstItem.language || "English";
const t = templates[language] || templates.English;

console.log('Facility response - Language:', language);
console.log('User question:', userQuestion);

// Build formatted response
let response = "";

// Add greeting based on number of results
if (items.length === 1) {
    response += `${t.foundSingle} "${userQuestion}":\n\n`;
} else {
    response += `${t.foundMultiple.replace('{count}', items.length)} "${userQuestion}":\n\n`;
}

// Format each facility
items.forEach((item, index) => {
    const fac = item.json;

    // Use language-appropriate fields
    const name = fac[`Name_${language}`] || fac.Name_English || fac.Facility_Name || 'Facility';
    const category = fac[`Category_${language}`] || fac.Category_English || '';
    const location = fac[`Location_${language}`] || fac.Location_English || '';
    const capacity = fac[`Capacity_${language}`] || fac.Capacity_English || '';
    const amenities = fac[`Amenities_${language}`] || fac.Amenities_English || '';
    const timing = fac[`Timing_${language}`] || fac.Timing_English || '';
    const contact = fac.Contact || '';
    const mapLink = fac.Map_Link || '';

    // Facility name/title
    response += `*${index + 1}. ${name}*\n`;

    // Category
    if (category) {
        response += `   ${t.category}: ${category}\n`;
    }

    // Location
    if (location) {
        response += `   ${t.location}: ${location}\n`;
    }

    // Capacity
    if (capacity) {
        response += `   ${t.capacity}: ${capacity}\n`;
    }

    // Amenities
    if (amenities) {
        response += `   ${t.amenities}: ${amenities}\n`;
    }

    // Timing
    if (timing) {
