const items = $input.all();
const results = [];

let queryItem = null;

const infoItems = items.filter(item => {
    if (item.json.Category) {
        return true;
    }
    if (item.json.infoType || item.json.question) {
        queryItem = item.json;
    }
    return false;
});

if (!queryItem || !queryItem.question) {
    return [{ json: { error: 'General info query data missing.' } }];
}

const queryQuestion = queryItem.question;
const queryLanguage = queryItem.language || "English";

console.log('=== GENERAL INFO QUERY DEBUG ===');
console.log('Query:', queryQuestion);
console.log('Language:', queryLanguage);

function normalizeText(text) {
    if (!text) return '';
    return text.toLowerCase().replace(/\s+/g, ' ').trim();
}

const queryLower = normalizeText(queryQuestion);
const queryWords = queryLower.split(/\s+/).filter(w => w.length >= 2);

// Detect query types
const isTransportQuery = queryLower.match(/\b(car|bus|train|flight|air|reach|come|go|travel|transport)\b/);
const isDistanceQuery = queryLower.match(/\b(far|distance|km|away|from delhi|from chandigarh|how far)\b/);
const isLocationQuery = isTransportQuery || isDistanceQuery;

console.log('Is Transport Query:', !!isTransportQuery);
console.log('Is Distance Query:', !!isDistanceQuery);
console.log('Query words:', queryWords);

// Extract city names from query
const cityNames = ['delhi', 'chandigarh', 'ambala', 'karnal', 'pehowa', 'thanesar'];
const mentionedCities = cityNames.filter(city => queryLower.includes(city));
console.log('Mentioned cities:', mentionedCities);

// Language-specific answer field
const answerField = `Answer_${queryLanguage}`;
const fallbackAnswerField = 'Answer_English';
const questionField = `Question_${queryLanguage}`;

for (const item of infoItems) {
    const info = item.json;
    const subCategory = normalizeText(info.Sub_Category || '').replace(/_/g, ' ');
    const answer = info[answerField] || info[fallbackAnswerField] || info.Answer || '';
    const question = info[questionField] || info.Question_English || '';
    const searchwords = normalizeText(info.English_Searchwords || info.Hindi_Searchwords || '');

    let matchScore = 0;
    const matchedKeywords = [];

    const normalizedQuestion = normalizeText(question);
    const normalizedAnswer = normalizeText(answer);

    console.log(`\n--- Checking: ${info.Sub_Category} ---`);

    // CRITICAL: Special handling for "How to Reach" with transport/distance queries
    if (isLocationQuery && subCategory.includes('reach')) {
        matchScore += 100;
        matchedKeywords.push('LOCATION+REACH_CATEGORY');
        console.log('✅ Location/Transport query + How_To_Reach category: +100 points');
    }

    // Bonus for city name matches in answer
    let cityMatches = 0;
    for (const city of mentionedCities) {
        if (normalizedAnswer.includes(city)) {
            cityMatches++;
            matchScore += 50;
            matchedKeywords.push(`${city}(CITY-MATCH)`);
            console.log(`✅ City "${city}" found in answer: +50 points`);
        }
    }

    // Match query words in searchwords
    let swMatches = 0;
    for (const word of queryWords) {
        if (word.length >= 3 && searchwords.includes(word)) {
            swMatches++;
            matchScore += 30;
            matchedKeywords.push(`${word}(SW)`);
        }
    }

    // Match query words in answer
    let aMatches = 0;
    for (const word of queryWords) {
        if (word.length >= 3 && normalizedAnswer.includes(word)) {
            aMatches++;
            matchScore += 20;
            matchedKeywords.push(`${word}(A)`);
        }
    }

    // Match query words in question
    let qMatches = 0;
    for (const word of queryWords) {
        if (word.length >= 3 && normalizedQuestion.includes(word)) {
            qMatches++;
            matchScore += 40;
            matchedKeywords.push(`${word}(Q)`);
        }
    }

    console.log(`Score: ${matchScore}, Cities: ${cityMatches}, SW: ${swMatches}, A: ${aMatches}, Q: ${qMatches}`);

    // Lower threshold for location/transport queries
    const threshold = isLocationQuery ? 30 : 50;

    if (matchScore >= threshold) {
        console.log('✅ MATCH FOUND!');
        results.push({
            json: {
                "Category": info.Category,
                "Sub_Category": info.Sub_Category,
                "Question": question,
                "Answer": answer,
                "queryQuestion": queryQuestion,
                "language": queryLanguage,
                "source": 'General Information',
                "matchScore": matchScore,
                "matchedKeywords": matchedKeywords.join(', ')
            }
        });
    }
}

results.sort((a, b) => b.json.matchScore - a.json.matchScore);

console.log(`\n=== FINAL: Found ${results.length} matching results ===`);

if (results.length > 0) {
    // Return top result if significantly better
    if (results.length >= 2 && (results[0].json.matchScore - results[1].json.matchScore) >= 50) {
        return [results[0]];
    }
    return results.slice(0, 2);
} else {
    return [{
        json: {
            message: 'I could not find specific information for your query.',
            searchedFor: queryQuestion,
            suggestion: 'Please try asking about dates, timings, entry fees, places to visit, or how to reach Kurukshetra.',
            queryQuestion: queryQuestion,
            language: queryLanguage
        }
    }];
}

