        matchScore += 3;
        matchedKeywords.push('has entry fee');
    } else if (queryType === 'location' && place.How_To_Reach) {
        matchScore += 3;
        matchedKeywords.push('has location info');
    }

    // Threshold: Accept if score >= 10
    if (matchScore >= 10) {
        results.push({
            json: {
                "Place_Name": place.Place_Name,
                "Location": place.Location,
                "Description": place.Description,
                "Entry_Fee": place.Entry_Fee,
