// Filters emergency services by type and keywords
// Supports: Police, Fire, Lost Child, Rescue, Tourist Help, etc.

const items = $input.all();
const results = [];

let queryItem = null;

// Separate emergency data from query data
const emergencyItems = items.filter(item => {
    // Check if this is emergency data
    if (item.json.Type_English || item.json.Emergency_ID) {
        return true;
    }
    // Check if this is query data
    if (item.json.emergencyKeywords || item.json.queryQuestion) {
        queryItem = item.json;
    }
    return false;
});

// Validate we have query data
if (!queryItem || !queryItem.queryQuestion) {
    return [{ json: { error: 'Emergency query data missing.' } }];
}

const queryQuestion = queryItem.queryQuestion;
const queryLanguage = queryItem.language || "English";
const emergencyKeywords = queryItem.emergencyKeywords || '';

console.log('=== EMERGENCY QUERY DEBUG ===');
console.log('Query:', queryQuestion);
console.log('Language:', queryLanguage);
console.log('Keywords:', emergencyKeywords);
console.log('Total emergency entries:', emergencyItems.length);

// Normalize text function (with safety check)
function normalizeText(text) {
    if (!text) return '';
    // Convert to string first (safety check)
    const textStr = String(text);
    return textStr.toLowerCase().replace(/\s+/g, ' ').trim();
}

// Extract query words (minimum 2 characters)
let queryWords = normalizeText(queryQuestion + ' ' + emergencyKeywords)
    .split(/\s+/)
    .filter(w => w.length >= 2);

console.log('Query words:', queryWords.join(', '));

// Detect emergency type from query
const emergencyTypeDetection = {
    police: queryWords.some(w => w.includes('police') || w.includes('पुलिस') || w.includes('security') || w.includes('सुरक्षा')),
    lostChild: queryWords.some(w => w.includes('child') || w.includes('बच्चा') || w.includes('बच्चे') || w.includes('lost') || w.includes('खो') || w.includes('गुम') || w.includes('missing')),
    lostFound: queryWords.some(w => w.includes('lost') || w.includes('found') || w.includes('खोया') || w.includes('पाया') || w.includes('गुम')),
    fire: queryWords.some(w => w.includes('fire') || w.includes('आग') || w.includes('फायर') || w.includes('101')),
    rescue: queryWords.some(w => w.includes('rescue') || w.includes('diver') || w.includes('बचाव') || w.includes('गोताखोर') || w.includes('drowning') || w.includes('डूब')),
    tourist: queryWords.some(w => w.includes('tourist') || w.includes('पर्यटक') || w.includes('information') || w.includes('जानकारी')),
    medical: queryWords.some(w => w.includes('medical') || w.includes('doctor') || w.includes('hospital') || w.includes('चिकित्सा') || w.includes('डॉक्टर') || w.includes('ambulance')),
    helpline: queryWords.some(w => w.includes('helpline') || w.includes('हेल्पलाइन') || w.includes('number') || w.includes('नंबर') || w.includes('contact') || w.includes('संपर्क')),
    emergency: queryWords.some(w => w.includes('emergency') || w.includes('आपातकाल') || w.includes('help') || w.includes('मदद'))
};

console.log('Emergency type detection:', emergencyTypeDetection);

// Process each emergency entry
for (const item of emergencyItems) {
    const emg = item.json;

    // Get fields based on language (NO template literals)
    const typeFieldName = 'Type_' + queryLanguage;
    const locationFieldName = 'Location_' + queryLanguage;
    const keywordsFieldName = 'Keywords_' + queryLanguage;
    const descriptionFieldName = 'Description_' + queryLanguage;

    const type = normalizeText(emg[typeFieldName] || emg.Type_English || '');
    const location = normalizeText(emg[locationFieldName] || emg.Location_English || '');
    const keywords = normalizeText(emg[keywordsFieldName] || emg.Keywords_English || '');
    const description = normalizeText(emg[descriptionFieldName] || emg.Description_English || '');
    const contact = normalizeText(emg.Contact || '');

    let matchScore = 0;
    const matchedKeywords = [];

    // 1. TYPE MATCHING (Most important - 30 points)
    let typeMatched = false;

    if (emergencyTypeDetection.police && (type.includes('police') || type.includes('पुलिस'))) {
        matchScore += 30;
        matchedKeywords.push('Police');
        typeMatched = true;
    }

    if (emergencyTypeDetection.lostChild && (type.includes('child') || type.includes('बच्चा') || type.includes('बाल'))) {
        matchScore += 35;  // Higher priority for lost child
        matchedKeywords.push('Child Helpline');
        typeMatched = true;
    }

    if (emergencyTypeDetection.lostFound && (type.includes('lost') || type.includes('found') || type.includes('खोया'))) {
        matchScore += 30;
        matchedKeywords.push('Lost & Found');
        typeMatched = true;
    }

    if (emergencyTypeDetection.fire && (type.includes('fire') || type.includes('फायर') || type.includes('आग') || type.includes('brigade'))) {
        matchScore += 50;  // Highest priority for fire - very urgent
        matchedKeywords.push('Fire Brigade');
        typeMatched = true;
    }

    if (emergencyTypeDetection.rescue && (type.includes('rescue') || type.includes('diver') || type.includes('बचाव') || type.includes('गोताखोर'))) {
        matchScore += 30;
        matchedKeywords.push('Rescue Team');
        typeMatched = true;
    }

    if (emergencyTypeDetection.tourist && (type.includes('tourist') || type.includes('पर्यटक'))) {
        matchScore += 25;
        matchedKeywords.push('Tourist Help');
        typeMatched = true;
    }

    if (emergencyTypeDetection.medical && (type.includes('ambulance') || type.includes('medical') || type.includes('चिकित्सा') || type.includes('एम्बुलेंस'))) {
        matchScore += 40;  // High priority for medical emergency
        matchedKeywords.push('Medical Emergency');
        typeMatched = true;
    }

    // 2. KEYWORD MATCHING (High priority - 20 points max)
    if (keywords) {
        let keywordMatches = 0;
        for (const word of queryWords) {
            if (word.length < 2) continue;

            if (keywords.includes(word)) {
                keywordMatches++;
                matchedKeywords.push(word + ' (keyword)');
            }
        }
        matchScore += Math.min(keywordMatches * 4, 20);
    }

    // 3. SPECIAL CASES - Generic emergency/help queries
    if (emergencyTypeDetection.emergency || emergencyTypeDetection.helpline) {
        // Only if no specific type matched, show common emergency services
        if (!typeMatched) {
            if (type.includes('police') || type.includes('fire') || type.includes('child') || 
                type.includes('ambulance') || type.includes('medical') ||
                type.includes('पुलिस') || type.includes('आग') || type.includes('बच्चा') || 
                type.includes('एम्बुलेंस') || type.includes('चिकित्सा')) {
                matchScore += 25;
                matchedKeywords.push('General Emergency');
            }
        }
    }


    // 4. CONTACT/DESCRIPTION MATCHING (Bonus 10 points)
    for (const word of queryWords) {
        if (word.length < 3) continue;
        if (description.includes(word) || contact.includes(word)) {
            matchScore += 2;
        }
    }

    // THRESHOLD: Minimum 20 points to be included (more selective)
    if (matchScore >= 20) {
        results.push({
            json: {
                "Emergency_ID": emg.Emergency_ID,
                "Type_English": emg.Type_English,
                "Type_Hindi": emg.Type_Hindi,
                "Contact": emg.Contact,
                "Location_English": emg.Location_English,
                "Location_Hindi": emg.Location_Hindi,
                "Map_Link": emg.Map_Link,
                "Description_English": emg.Description_English,
                "Description_Hindi": emg.Description_Hindi,
                "Timing_English": emg.Timing_English,
                "Timing_Hindi": emg.Timing_Hindi,
                "queryQuestion": queryQuestion,
                "language": queryLanguage,
                "source": 'Emergency',
                "matchScore": matchScore,
                "matchedKeywords": matchedKeywords.join(', ')
            }
        });
    }
}

// Sort by match score (highest first)
results.sort((a, b) => b.json.matchScore - a.json.matchScore);

console.log('Found ' + results.length + ' matching emergency services');

// Return results (all matching emergency services)
if (results.length > 0) {
    console.log('Top 5 match scores:', results.slice(0, 5).map(r => r.json.matchScore));
    return results; // Return all results for emergencies
} else {
    // No matches found
    return [{
        json: {
            message: queryLanguage === 'Hindi' 
                ? 'कोई आपातकालीन सेवा नहीं मिली। पुलिस, फायर ब्रिगेड, या बाल हेल्पलाइन के बारे में पूछें।'
                : 'No emergency service found. Please ask about police, fire brigade, or child helpline.',
            searchedFor: queryQuestion,
            suggestion: queryLanguage === 'Hindi'
                ? 'पुलिस संपर्क, फायर ब्रिगेड, बच्चा खो गया, या आपातकालीन नंबर के बारे में पूछें।'
                : 'Try asking about police contact, fire brigade, lost child, or emergency numbers.',
            queryQuestion: queryQuestion,
            language: queryLanguage
        }
    }];
}

