const items = $input.all();
const results = [];

let queryItem = null;

const transportItems = items.filter(item => {
    if (item.json.From_City) {
        return true;
    }
    if (item.json.fromLocation || item.json.queryQuestion) {
        queryItem = item.json;
    }
    return false;
});

if (!queryItem || !queryItem.queryQuestion) {
    return [{ json: { error: 'Transport query data missing. Check Merge node.' } }];
}

const queryQuestion = queryItem.queryQuestion;
const queryLanguage = queryItem.language || "English";
const fromLocation = (queryItem.fromLocation || '').toLowerCase();
const transportMode = (queryItem.transportMode || '').toLowerCase();
const queryType = (queryItem.queryType || '').toLowerCase();

console.log('=== TRANSPORT QUERY DEBUG INFO ===');
console.log('Query:', queryQuestion);
console.log('Language:', queryLanguage);
console.log('From Location:', fromLocation);
console.log('Transport Mode:', transportMode);
console.log('Total transport items:', transportItems.length);

function normalizeText(text) {
    return text.toLowerCase().replace(/\s+/g, ' ').trim();
}

const queryWords = normalizeText(queryQuestion)
    .split(/\s+/)
    .filter(w => w.length >= 3);

// City name variations
const cityVariations = {
    'delhi': ['delhi', 'new delhi', 'ndls'],
    'chandigarh': ['chandigarh', 'chd'],
    'amritsar': ['amritsar', 'asr'],
    'jaipur': ['jaipur', 'jp'],
    'lucknow': ['lucknow', 'lko']
};

// Transport mode keywords
const modeKeywords = {
    'train': ['train', 'railway', 'shatabdi', 'express', 'rail'],
    'bus': ['bus', 'roadways', 'volvo', 'coach'],
    'flight': ['flight', 'airport', 'air', 'fly'],
    'taxi': ['taxi', 'cab', 'car', 'uber', 'ola'],
    'auto': ['auto', 'rickshaw'],
    'shuttle': ['shuttle', 'local']
};

// Find matching cities
let matchingCities = [fromLocation];
for (const [city, variations] of Object.entries(cityVariations)) {
    if (variations.some(v => fromLocation.includes(v) || queryWords.includes(v))) {
        if (!matchingCities.includes(city)) {
            matchingCities.push(city);
        }
    }
}

// Find matching transport modes
let matchingModes = [transportMode];
for (const [mode, keywords] of Object.entries(modeKeywords)) {
    if (keywords.some(k => transportMode.includes(k) || queryWords.includes(k))) {
        if (!matchingModes.includes(mode)) {
            matchingModes.push(mode);
        }
    }
}

console.log('Matching cities:', matchingCities);
console.log('Matching modes:', matchingModes);

for (const item of transportItems) {
    const transport = item.json;
    const fromCity = normalizeText(transport.From_City || '');
    const mode = normalizeText(transport.Transport_Mode || '');
    const serviceName = normalizeText(transport.Service_Name || '');
    const details = normalizeText(transport.Details || '');

    let matchScore = 0;
    const matchedKeywords = [];

    // 1. City matching (Most important - 15 points)
    for (const city of matchingCities) {
        if (fromCity.includes(city) || city.includes(fromCity)) {
            matchScore += 15;
            matchedKeywords.push(`${city} (from city)`);
            break;
        }
    }

    // 2. Transport mode matching (High priority - 10 points)
    for (const m of matchingModes) {
        if (mode.includes(m) || m.includes(mode) || serviceName.includes(m)) {
            matchScore += 10;
            matchedKeywords.push(`${m} (mode)`);
            break;
        }
    }

    // 3. Query word matching
    for (const word of queryWords) {
        if (word.length < 3) continue;

        if (serviceName.includes(word)) {
            matchScore += 3;
            matchedKeywords.push(`${word} (service)`);
        } else if (details.includes(word)) {
            matchScore += 2;
            matchedKeywords.push(`${word} (details)`);
        }
    }

    // 4. Query type bonus
    if (queryType === 'timings' && transport.Duration) {
        matchScore += 2;
    } else if (queryType === 'cost' && transport.Approximate_Cost) {
        matchScore += 2;
    }

    // Threshold: >= 15
    if (matchScore >= 15) {
        results.push({
            json: {
                "From_City": transport.From_City,
                "Transport_Mode": transport.Transport_Mode,
                "Service_Name": transport.Service_Name,
                "Details": transport.Details,
                "Duration": transport.Duration,
                "Approximate_Cost": transport.Approximate_Cost,
                "Frequency": transport.Frequency,
                "Contact": transport.Contact,
                "queryQuestion": queryQuestion,
                "language": queryLanguage,
                "source": 'Transport Info',
                "matchScore": matchScore,
                "matchedKeywords": matchedKeywords.join(', ')
            }
        });
    }
}

results.sort((a, b) => b.json.matchScore - a.json.matchScore);

if (results.length > 0) {
    console.log(`Found ${results.length} transport options`);
    return results.slice(0, 5);
} else {
    return [{
        json: {
            message: 'No transport options found for your route.',
            searchedFor: queryQuestion,
            suggestion: 'Try asking about transport from Delhi, Chandigarh, or Amritsar.',
            queryQuestion: queryQuestion,
            language: queryLanguage
        }
    }];
}

