        }
    }];
}

const language = firstItem.language || "English";
const t = templates[language] || templates.English;

let response = "";

if (items.length === 1) {
    response += `${t.foundSingle} "${userQuestion}":\n\n`;
} else {
    response += `${t.foundMultiple.replace('{count}', items.length)} "${userQuestion}":\n\n`;
}

items.forEach((item, index) => {
    const transport = item.json;

    response += `*${index + 1}. ${transport.Service_Name || transport.Transport_Mode}*\n`;

    if (transport.From_City) {
        response += `   ${t.from}: ${transport.From_City}\n`;
    }

    if (transport.Transport_Mode) {
        response += `   ${t.mode}: ${transport.Transport_Mode}\n`;
    }

    if (transport.Details) {
        response += `   ${t.details}: ${transport.Details}\n`;
    }

    if (transport.Duration) {
        response += `   ${t.duration}: ${transport.Duration}\n`;
    }

    if (transport.Approximate_Cost) {
        response += `   ${t.cost}: ${transport.Approximate_Cost}\n`;
    }

    if (transport.Frequency) {
        response += `   ${t.frequency}: ${transport.Frequency}\n`;
    }

    if (transport.Contact) {
        response += `   ${t.contact}: ${transport.Contact}\n`;
    }

    response += `\n`;
});

response += `${t.footer}`;

return [{
    json: {
        response: response,
        success: true,
        totalResults: items.length,
        userQuestion: userQuestion,
        language: language
    }
}];

// --- Code for 4e. Filter Accommodation (UPDATED FOR NEW DATABASE) ---
// Uses Keywords_English/Keywords_Hindi for better matching
// Supports facility filtering (AC, Parking, Mess, Temple, TV, RO, Geyser, Hall, Generator)
// No result limit - returns all matches above threshold
// FIXED: Now properly handles "TV in rooms?" type queries

const items = $input.all();
const results = [];

let queryItem = null;

// Separate accommodation data from query data
const accommodationItems = items.filter(item => {
    // Check if this is accommodation data (has Name_English field)
    if (item.json.Name_English || item.json.Type === 'Dharamshala') {
        return true;
    }
    // Check if this is query data
    if (item.json.accommodationKeywords || item.json.queryQuestion) {
        queryItem = item.json;
    }
    return false;
});

// Validate we have query data
if (!queryItem || !queryItem.queryQuestion) {
    return [{ json: { error: 'Accommodation query data missing.' } }];
}

const queryQuestion = queryItem.queryQuestion;
const queryLanguage = queryItem.language || "English";
const accommodationKeywords = queryItem.accommodationKeywords || '';

console.log('=== ACCOMMODATION QUERY DEBUG ===');
console.log('Query:', queryQuestion);
console.log('Language:', queryLanguage);
console.log('Keywords:', accommodationKeywords);
console.log('Total accommodation entries:', accommodationItems.length);

// Normalize text function
function normalizeText(text) {
    if (!text) return '';
    return text.toLowerCase().replace(/\s+/g, ' ').trim();
}

// Normalize plural/singular and common variations
function normalizeWord(word) {
    // Remove plural 's' for better matching
    if (word.endsWith('s') && word.length > 3) {
        return word.slice(0, -1); // dharamshalas → dharamshala
    }
    return word;
}

// Extract query words (minimum 2 characters)
let queryWords = normalizeText(queryQuestion + ' ' + accommodationKeywords)
    .split(/\s+/)
    .filter(w => w.length >= 2)
    .map(w => normalizeWord(w)); // Normalize each word

console.log('Query words:', queryWords.join(', '));

// Detect if this is a BROAD query (just asking for general dharamshalas)
// Don't treat bedroom-specific queries as broad queries
const isBroadQuery = queryWords.some(w => ['dharamshala', 'hotel', 'accommodation', 'stay', 'lodge', 'धर्मशाला', 'आवास'].includes(w)) &&
    queryWords.length <= 4 && // Short query
    !queryWords.some(w => ['ac', 'parking', 'mess', 'temple', 'एसी', 'पार्किंग', 'single', 'double', 'dormitory', 'एक', 'डबल', 'सामूहिक'].includes(w)); // No specific facilities or bedroom types

// Detect landmark/location-based queries
const locationLandmarks = {
    brahmaSarovar: queryWords.some(w => ['brahma', 'sarovar', 'ब्रह्म', 'सरोवर'].includes(w)),
    railwayStation: queryWords.some(w => ['railway', 'station', 'रेलवे', 'स्टेशन'].includes(w)),
    busStand: queryWords.some(w => ['bus', 'stand', 'बस', 'स्टैंड'].includes(w)),
    krishnaGate: queryWords.some(w => ['krishna', 'gate', 'कृष्णा', 'गेट'].includes(w)),
    birlaMandir: queryWords.some(w => ['birla', 'mandir', 'बिड़ला', 'मंदिर'].includes(w)),
    jyotisar: queryWords.some(w => ['jyotisar', 'ज्योतिसर'].includes(w)),
    kuk: queryWords.some(w => ['kuk', 'university', 'कुरुक्षेत्र', 'यूनिवर्सिटी'].includes(w)),
    near: queryWords.some(w => ['near', 'nearby', 'close', 'पास', 'नजदीक', 'निकट'].includes(w))
};

const isLocationQuery = locationLandmarks.near || 
    locationLandmarks.brahmaSarovar || 
    locationLandmarks.railwayStation || 
    locationLandmarks.busStand ||
    locationLandmarks.krishnaGate ||
    locationLandmarks.birlaMandir ||
    locationLandmarks.jyotisar ||
    locationLandmarks.kuk;

console.log('Is broad query:', isBroadQuery);
console.log('Is location query:', isLocationQuery);
console.log('Location landmarks:', locationLandmarks);

// Detect facility requirements from query (MAIN 4 FACILITIES - MUST HAVE)
const facilityRequirements = {
    hasAC: queryWords.some(w => ['ac', 'एसी', 'air', 'conditioned', 'वातानुकूलित', 'conditioning'].includes(w)),
    hasParking: queryWords.some(w => ['parking', 'पार्किंग', 'vehicle', 'car', 'गाड़ी'].includes(w)),
    hasMess: queryWords.some(w => ['mess', 'canteen', 'food', 'भोजन', 'खाना', 'भोजनालय', 'मेस', 'dining', 'meals'].includes(w)),
    hasTemple: queryWords.some(w => ['temple', 'mandir', 'मंदिर', 'धार्मिक', 'religious'].includes(w))
};

// Detect additional facility preferences (NICE TO HAVE - ADDS SCORE)
const additionalFacilities = {
    tv: queryWords.some(w => ['tv', 'टीवी', 'television'].includes(w)),
    ro: queryWords.some(w => ['ro', 'water', 'पानी'].includes(w)),
    geyser: queryWords.some(w => ['geyser', 'hot', 'गरम', 'गीजर'].includes(w)),
    hall: queryWords.some(w => ['hall', 'हॉल', 'meeting', 'gathering', 'बैठक'].includes(w)),
    generator: queryWords.some(w => ['generator', 'जनरेटर', 'power', 'backup'].includes(w)),
    cooler: queryWords.some(w => ['cooler', 'कूलर'].includes(w))
};

// Detect bedroom type preferences
// Check for bedroom type queries in multiple ways for robustness
const hasBedOrRoomWord = queryWords.some(w => ['bed', 'beds', 'bedroom', 'bedrooms', 'room', 'rooms', 'कमरा', 'बेड'].includes(w));

const bedroomTypePreference = {
    single: (queryWords.includes('single') || queryWords.includes('एक') || queryWords.includes('सिंगल') || queryWords.includes('one')) && hasBedOrRoomWord,
    double: (queryWords.includes('double') || queryWords.includes('डबल') || queryWords.includes('couple') || queryWords.includes('two')) && hasBedOrRoomWord,
    dormitory: queryWords.some(w => ['dormitory', 'dorm', 'सामूहिक', 'shared', 'साझा', 'common'].includes(w))
};

console.log('Has bed/room word:', hasBedOrRoomWord);
console.log('Bedroom type preference:', bedroomTypePreference);

console.log('Facility requirements (MUST HAVE):', facilityRequirements);
console.log('Additional facilities (PREFERRED):', additionalFacilities);
console.log('Bedroom type preference:', bedroomTypePreference);

// Detect category preferences
const categoryPreference = {
    budget: queryWords.some(w => ['budget', 'cheap', 'affordable', 'free', 'सस्ता', 'मुफ्त', 'donation'].includes(w)),
    large: queryWords.some(w => ['large', 'big', 'बड़ा', 'capacity', 'spacious'].includes(w)),
    medium: queryWords.some(w => ['medium', 'moderate', 'मध्यम'].includes(w))
};

// Detect if this is a "facility in rooms" type query
const isFacilityInRoomsQuery = queryWords.includes('in') && 
    (queryWords.includes('rooms') || queryWords.includes('room'));

console.log('Is facility-in-rooms query:', isFacilityInRoomsQuery);

// Process each accommodation entry
for (const item of accommodationItems) {
    const acc = item.json;

    // Get fields based on language
    const name = normalizeText(acc[`Name_${queryLanguage}`] || acc.Name_English || '');
    const location = normalizeText(acc[`Location_${queryLanguage}`] || acc.Location_English || '');
    const keywords = normalizeText(acc[`Keywords_${queryLanguage}`] || acc.Keywords_English || '');
    const facilities = normalizeText(acc[`Facilities_${queryLanguage}`] || acc.Facilities_English || '');
    const description = normalizeText(acc[`Description_${queryLanguage}`] || acc.Description_English || '');
    const category = normalizeText(acc.Category || '');
    const priceRange = normalizeText(acc.Price_Range || '');

    let matchScore = 0;
    const matchedKeywords = [];

    // 1. KEYWORD MATCHING (Most important - 30 points max)
    // Keywords field contains 20-50 comprehensive keywords
    if (keywords) {
        let keywordMatches = 0;
        for (const word of queryWords) {
            if (word.length < 2) continue;

            // For better matching, check if keyword contains the word (not just exact word boundaries)
            // This handles plurals, variations, etc.
            if (keywords.includes(word)) {
                keywordMatches++;
                matchedKeywords.push(`${word} (keyword)`);
            }
        }
        // Award points based on keyword matches (up to 30 points)
        matchScore += Math.min(keywordMatches * 3, 30);
    }

    // 2. NAME MATCHING (20 points)
    let nameMatches = 0;
    for (const word of queryWords) {
        if (word.length < 2) continue;
        if (name.includes(word)) {
            nameMatches++;
            matchedKeywords.push(`${word} (name)`);
        }
    }
    if (nameMatches > 0) {
        matchScore += Math.min(nameMatches * 10, 20);
    }

    // 3. LOCATION MATCHING (10 points)
    let locationMatches = 0;
    for (const word of queryWords) {
        if (word.length < 2) continue;
        if (location.includes(word)) {
            locationMatches++;
            matchedKeywords.push(`${word} (location)`);
        }
    }
    if (locationMatches > 0) {
        matchScore += Math.min(locationMatches * 5, 10);
    }

    // 4. FACILITY FILTERING - MAIN 4 FACILITIES (MUST MATCH if specified)
    let facilityMatch = true;
    let facilityBonus = 0;

    if (facilityRequirements.hasAC) {
        if (acc.Has_AC === 'Yes') {
            facilityBonus += 10;
            matchedKeywords.push('AC available');
        } else {
            facilityMatch = false; // EXCLUDE if AC required but not available
        }
    }

    if (facilityRequirements.hasParking) {
        if (acc.Has_Parking === 'Yes') {
            facilityBonus += 10;
            matchedKeywords.push('Parking available');
        } else {
            facilityMatch = false; // EXCLUDE if Parking required but not available
        }
    }

    if (facilityRequirements.hasMess) {
        if (acc.Has_Mess === 'Yes') {
            facilityBonus += 10;
            matchedKeywords.push('Mess available');
        } else {
            facilityMatch = false; // EXCLUDE if Mess required but not available
        }
    }

    if (facilityRequirements.hasTemple) {
        if (acc.Has_Temple === 'Yes') {
            facilityBonus += 10;
            matchedKeywords.push('Temple available');
        } else {
            facilityMatch = false; // EXCLUDE if Temple required but not available
        }
    }

    // If required facilities not met, skip this entry
    if (!facilityMatch) {
        continue;
    }

    matchScore += facilityBonus;

    // 5. ADDITIONAL FACILITY MATCHING (TV, RO, Geyser, Hall, Generator, Cooler)
    // These are PREFERRED facilities - they add to score but don't exclude results

    if (additionalFacilities.tv) {
        if (facilities.includes('tv') || facilities.includes('टीवी')) {
            matchScore += 15;  // High score for TV match
            matchedKeywords.push('TV available');
        }
    }

    if (additionalFacilities.ro) {
        if (facilities.includes('ro') || facilities.includes('आरओ')) {
            matchScore += 12;
            matchedKeywords.push('RO water available');
        }
    }

    if (additionalFacilities.geyser) {
        if (facilities.includes('geyser') || facilities.includes('गीजर')) {
            matchScore += 12;
            matchedKeywords.push('Geyser available');
        }
    }

    if (additionalFacilities.hall) {
        if (facilities.includes('hall') || facilities.includes('हॉल')) {
            matchScore += 10;
            matchedKeywords.push('Hall available');
        }
    }

    if (additionalFacilities.generator) {
        if (facilities.includes('generator') || facilities.includes('जनरेटर')) {
            matchScore += 10;
            matchedKeywords.push('Generator available');
        }
    }

    if (additionalFacilities.cooler) {
        if (facilities.includes('cooler') || facilities.includes('कूलर')) {
            matchScore += 8;
            matchedKeywords.push('Cooler available');
        }
    }

    // 5B. BEDROOM TYPE MATCHING
    // If user asks for specific bedroom type, boost score if available
    let bedroomTypeMatch = true; // Start as true, only set false if requirement not met

    if (bedroomTypePreference.single) {
        if (acc.Single_Beds && acc.Single_Beds > 0) {
            matchScore += 15;
            matchedKeywords.push(`Single bed rooms available (${acc.Single_Beds} beds)`);
        } else {
            // Don't exclude, just don't give bonus
            matchedKeywords.push('No single bed rooms');
        }
    }

    if (bedroomTypePreference.double) {
        if (acc.Double_Beds && acc.Double_Beds > 0) {
            matchScore += 15;
            matchedKeywords.push(`Double bed rooms available (${acc.Double_Beds} beds)`);
        } else {
            // Don't exclude, just don't give bonus
            matchedKeywords.push('No double bed rooms');
        }
    }

    if (bedroomTypePreference.dormitory) {
        if (acc.Dormitory_Beds && acc.Dormitory_Beds > 0) {
            matchScore += 15;
            matchedKeywords.push(`Dormitory available (${acc.Dormitory_Beds} beds)`);
        } else {
            // Don't exclude, just don't give bonus
            matchedKeywords.push('No dormitory');
        }
    }

    // 6. SPECIAL HANDLING: "Facility in rooms" queries
    if (isFacilityInRoomsQuery) {
        // User is asking about room facilities specifically
        // Give extra boost if we found the requested facility
        const foundRequestedFacility = matchedKeywords.some(kw => 
            kw.includes('TV available') || 
            kw.includes('AC available') || 
            kw.includes('Geyser available')
        );

        if (foundRequestedFacility) {
            matchScore += 5;  // Extra boost for "in rooms" context
            matchedKeywords.push('Room facility match');
        }
    }

    // 7. CATEGORY MATCHING (5 points)
    if (categoryPreference.budget && (category.includes('budget') || priceRange.includes('free'))) {
        matchScore += 5;
        matchedKeywords.push('Budget category');
    }
    if (categoryPreference.large && (category.includes('large') || acc.Total_Beds > 50)) {
        matchScore += 5;
        matchedKeywords.push('Large capacity');
    }
    if (categoryPreference.medium && category.includes('medium')) {
        matchScore += 5;
        matchedKeywords.push('Medium size');
    }

    // 8. DESCRIPTION MATCHING (bonus 5 points)
    let descMatches = 0;
    for (const word of queryWords) {
        if (word.length >= 4 && description.includes(word)) {
            descMatches++;
        }
    }
    if (descMatches > 0) {
        matchScore += Math.min(descMatches * 2, 5);
        matchedKeywords.push('Description match');
    }

    // 9. BROAD QUERY BOOST
    // If this is a broad query (like "Dharamshalas in Kurukshetra"), 
    // give all dharamshalas a base score so they all appear
    if (isBroadQuery && acc.Type === 'Dharamshala') {
        matchScore += 10; // Base score for all dharamshalas in broad queries
        matchedKeywords.push('Dharamshala (broad query)');
    }

    // 9B. BEDROOM-SPECIFIC QUERY BOOST
    // If this is a bedroom-specific query, give all dharamshalas a base score
    if ((bedroomTypePreference.single || bedroomTypePreference.double || bedroomTypePreference.dormitory) && acc.Type === 'Dharamshala') {
        matchScore += 5; // Base score for bedroom queries to ensure results appear
        matchedKeywords.push('Bedroom query');
    }

    // 10. LOCATION LANDMARK MATCHING
    // Special handling for landmark-based location queries
    if (isLocationQuery) {
        // For Brahma Sarovar queries - ALL dharamshalas in Kurukshetra/Thanesar are reasonably close
        if (locationLandmarks.brahmaSarovar) {
            if (location.includes('kurukshetra') || location.includes('thanesar') || 
                location.includes('कुरुक्षेत्र') || location.includes('थानेसर')) {
                matchScore += 15; // Good score - in Kurukshetra area
                matchedKeywords.push('Near Brahma Sarovar (Kurukshetra area)');
            }
            // Extra boost if location specifically mentions brahma sarovar or nearby areas
            if (acc.Distance_From_Brahma_Sarovar || location.includes('brahma') || location.includes('ब्रह्म')) {
                matchScore += 10;
                matchedKeywords.push('Very close to Brahma Sarovar');
            }
        }

        // Railway Station queries
        if (locationLandmarks.railwayStation) {
            if (location.includes('railway') || location.includes('रेलवे') || 
                keywords.includes('railway') || keywords.includes('station')) {
                matchScore += 20; // High score for railway station proximity
                matchedKeywords.push('Near Railway Station');
            }
        }

        // Krishna Gate queries
        if (locationLandmarks.krishnaGate) {
            if (location.includes('krishna gate') || location.includes('कृष्णा गेट')) {
                matchScore += 20;
                matchedKeywords.push('At Krishna Gate');
            }
        }

        // Birla Mandir queries
        if (locationLandmarks.birlaMandir) {
            if (location.includes('birla') || name.includes('birla') || 
                location.includes('बिड़ला') || name.includes('बिड़ला')) {
                matchScore += 20;
                matchedKeywords.push('At Birla Mandir');
            }
        }

        // Bus Stand queries
        if (locationLandmarks.busStand) {
            if (location.includes('bus') || keywords.includes('bus stand') || 
                location.includes('बस') || keywords.includes('बस स्टैंड')) {
                matchScore += 15;
                matchedKeywords.push('Near Bus Stand');
            }
        }

        // Jyotisar queries
        if (locationLandmarks.jyotisar) {
            if (location.includes('jyotisar') || keywords.includes('jyotisar') ||
                location.includes('ज्योतिसर')) {
                matchScore += 20;
                matchedKeywords.push('Near Jyotisar');
            }
        }

        // KUK / University queries
        if (locationLandmarks.kuk) {
            if (location.includes('kuk') || keywords.includes('university') ||
                acc.Distance_From_KU || location.includes('यूनिवर्सिटी')) {
                matchScore += 15;
                matchedKeywords.push('Near KUK');
            }
        }

        // General "near" query with stay keyword - show all dharamshalas
        if (locationLandmarks.near && !locationLandmarks.brahmaSarovar && 
            !locationLandmarks.railwayStation && !locationLandmarks.busStand) {
            matchScore += 8; // Moderate boost for general proximity queries
            matchedKeywords.push('Accommodation in area');
        }
    }

    // THRESHOLD: Minimum 3 points to be included (LOWERED from 5)
    // Lower threshold ensures we get more results for broad queries
    if (matchScore >= 3) {
        results.push({
            json: {
                "Name_English": acc.Name_English,
                "Name_Hindi": acc.Name_Hindi,
                "Type": acc.Type,
                "Location_English": acc.Location_English,
                "Location_Hindi": acc.Location_Hindi,
                "Total_Beds": acc.Total_Beds,
                "Single_Beds": acc.Single_Beds,
                "Double_Beds": acc.Double_Beds,
                "Dormitory_Beds": acc.Dormitory_Beds,
                "Halls": acc.Halls,
                "Facilities_English": acc.Facilities_English,
                "Facilities_Hindi": acc.Facilities_Hindi,
                "Has_AC": acc.Has_AC,
                "Has_Parking": acc.Has_Parking,
                "Has_Mess": acc.Has_Mess,
                "Has_Temple": acc.Has_Temple,
                "Description_English": acc.Description_English,
                "Description_Hindi": acc.Description_Hindi,
                "Phone": acc.Phone,
                "Email": acc.Email,
                "Booking_Link": acc.Booking_Link,
                "Detail_Page_Link": acc.Detail_Page_Link,
                "Price_Range": acc.Price_Range,
                "Category": acc.Category,
                "Distance_From_Brahma_Sarovar": acc.Distance_From_Brahma_Sarovar,
                "Distance_From_KU": acc.Distance_From_KU,
                "Status": acc.Status,
                "queryQuestion": queryQuestion,
                "language": queryLanguage,
                "source": 'Accommodation',
                "matchScore": matchScore,
                "matchedKeywords": matchedKeywords.join(', ')
            }
        });
    }
}

// Sort by match score (highest first)
results.sort((a, b) => b.json.matchScore - a.json.matchScore);

console.log(`Found ${results.length} matching accommodations`);

// Return all results (NO LIMIT)
if (results.length > 0) {
    console.log('Top 5 match scores:', results.slice(0, 5).map(r => r.json.matchScore));
    console.log('Sample matched keywords:', results.slice(0, 3).map(r => r.json.matchedKeywords));
    return results; // Return ALL results
} else {
    // No matches found
    return [{
        json: {
            message: queryLanguage === 'Hindi' 
                ? 'कोई आवास नहीं मिला। कृपया पुनः प्रयास करें।'
                : 'No accommodation found matching your criteria.',
            searchedFor: queryQuestion,
            suggestion: queryLanguage === 'Hindi'
                ? 'होटल, धर्मशालाओं या कुरुक्षेत्र के आवास के बारे में पूछें।'
                : 'Try asking about hotels, dharamshalas, or accommodations in Kurukshetra.',
            queryQuestion: queryQuestion,
            language: queryLanguage
        }
    }];
}

