        queryItem = item.json;
    }
    return false;
});

if (!queryItem || !queryItem.queryQuestion) {
    return [{ json: { error: 'FAQ query data missing.' } }];
}

const queryQuestion = queryItem.queryQuestion;
const queryLanguage = queryItem.language || "English";
const faqCategory = (queryItem.faqCategory || '').toLowerCase();

console.log('=== FAQ QUERY DEBUG ===');
console.log('Query:', queryQuestion);
console.log('Language:', queryLanguage);
console.log('FAQ Category:', faqCategory);

function normalizeText(text) {
    return text.toLowerCase().replace(/\s+/g, ' ').trim();
}

const queryWords = normalizeText(queryQuestion)
    .split(/\s+/)
    .filter(w => w.length >= 3);

// FAQ category keywords
const faqKeywords = {
    'entry': ['entry', 'free', 'ticket', 'admission', 'fee', 'cost'],
    'safety': ['safe', 'safety', 'secure', 'family', 'women', 'children'],
    'photography': ['photo', 'camera', 'picture', 'photography', 'video'],
    'food': ['food', 'eat', 'meal', 'restaurant', 'canteen'],
    'parking': ['parking', 'park', 'vehicle', 'car'],
    'weather': ['weather', 'cold', 'hot', 'temperature', 'wear', 'clothes'],
    'accommodation': ['stay', 'hotel', 'accommodation', 'lodge']
};

let matchingCategories = [faqCategory];
for (const [category, keywords] of Object.entries(faqKeywords)) {
    if (keywords.some(k => faqCategory.includes(k) || queryWords.includes(k))) {
        if (!matchingCategories.includes(category)) {
            matchingCategories.push(category);
        }
    }
}

console.log('Matching FAQ categories:', matchingCategories);

// Language-specific fields
const questionField = `Question_${queryLanguage}`;
const answerField = `Answer_${queryLanguage}`;
