    const category = normalizeText(faq.FAQ_Category || '');
    const question = normalizeText(faq[questionField] || faq[fallbackQuestionField] || '');
    const answer = faq[answerField] || faq[fallbackAnswerField] || faq.Answer_English || '';

    let matchScore = 0;
    const matchedKeywords = [];

    // 1. Category match (15 points)
    if (matchingCategories.includes(category)) {
        matchScore += 15;
        matchedKeywords.push(`${category} (category)`);
    }

    // 2. Question similarity (word matching)
    const normalizedQueryQuestion = normalizeText(queryQuestion);
    for (const word of queryWords) {
        if (word.length < 3) continue;

        if (question.includes(word)) {
            matchScore += 5;
            matchedKeywords.push(`${word} (question)`);
        }
    }

    // 3. Language match bonus
    if (faq[answerField]) {
        matchScore += 5;
        matchedKeywords.push('language match');
    }

    // Threshold: >= 15
    if (matchScore >= 15) {
        results.push({
            json: {
                "FAQ_Category": faq.FAQ_Category,
                "Question": faq[questionField] || faq[fallbackQuestionField],
                "Answer": answer,
                "queryQuestion": queryQuestion,
                "language": queryLanguage,
                "source": 'FAQ',
                "matchScore": matchScore,
                "matchedKeywords": matchedKeywords.join(', ')
            }
        });
    }
}

results.sort((a, b) => b.json.matchScore - a.json.matchScore);

if (results.length > 0) {
