const questionField = queryLanguage === 'Hindi' ? 'Question_Hindi' : 'Question_English';
const answerField = queryLanguage === 'Hindi' ? 'Answer_Hindi' : 'Answer_English';
const fallbackQuestionField = 'Question_English';
const fallbackAnswerField = 'Answer_English';

// Score each quiz item
for (const item of quizItems) {
    const quiz = item.json;
    const category = normalizeText(quiz.Question_Category || '');

    const question = quiz[questionField] || quiz[fallbackQuestionField] || '';
    const answer = quiz[answerField] || quiz[fallbackAnswerField] || '';
    const questionText = normalizeText(question);

    let matchScore = 0;
    const matchedTerms = [];

    // 1. EXACT CATEGORY MATCH
    if (quizQueryType && category === quizQueryType) {
        matchScore += 150;
        matchedTerms.push('EXACT_CATEGORY');
    }

    // 2. Category partial match
    if (quizQueryType && matchScore < 150) {
        if (category.includes(quizQueryType)) {
            matchScore += 80;
            matchedTerms.push('cat_contains');
        }
        if (quizQueryType.includes(category) && category.length > 4) {
            matchScore += 70;
            matchedTerms.push('qtype_contains');
        }
    }

    // 3. Match query words in question
    let questionMatches = 0;
    for (const word of queryWords) {
        if (word.length >= 2 && questionText.includes(word)) {
            matchScore += 20;
            questionMatches++;
            matchedTerms.push('Q:' + word);
        }
    }

    // 3a. Intent-specific word matching (higher weight)
    // Words that indicate "receiving/getting" certificate
    const receivingWords = ['मिलेगा', 'मिल', 'प्राप्त', 'receive', 'get', 'होगा'];
    // Words that indicate "using" certificate (job/service)
    const usingWords = ['नौकरी', 'सेवा', 'use', 'job', 'service', 'छूट', 'relaxation', 'benefit'];

    for (const word of receivingWords) {
        if (queryNormalized.includes(word) && questionText.includes(word)) {
            matchScore += 35; // Boost for intent match
            matchedTerms.push('INTENT:receive');
            break;
        }
    }

    for (const word of usingWords) {
        if (queryNormalized.includes(word) && questionText.includes(word)) {
            matchScore += 35; // Boost for intent match
            matchedTerms.push('INTENT:use');
            break;
        }
    }

    // 4. Match language-appropriate keywords in question
    const relevantKeywords = queryLanguage === 'Hindi' ? hindiKeywords : englishKeywords;
    for (const keyword of relevantKeywords) {
        if (keyword.length >= 3 && questionText.includes(normalizeText(keyword))) {
            matchScore += 40;
            matchedTerms.push('KEY:' + keyword);
        }
    }

    // 5. Category keyword match
    for (const keyword of relevantKeywords) {
        if (keyword.length >= 3 && category.includes(normalizeText(keyword))) {
            matchScore += 10;
            matchedTerms.push('CAT_KEY');
        }
    }

    // 6. Phrase matching for Hindi
    if (queryLanguage === 'Hindi' && queryWords.length >= 3) {
        for (let i = 0; i <= queryWords.length - 3; i++) {
            const phrase = queryWords.slice(i, i + 3).join(' ');
            if (phrase.length > 8 && questionText.includes(phrase)) {
                matchScore += 30;
                matchedTerms.push('PHRASE');
                break;
            }
        }
    }

    // 7. Multi-match bonus
    if (questionMatches >= 3) {
        matchScore += 25;
        matchedTerms.push('MULTI');
    }

    // 8. Language bonus
    if (queryLanguage === 'Hindi' && quiz[answerField] && quiz[answerField].length > 10) {
        matchScore += 5;
        matchedTerms.push('LANG');
    }

    if (matchScore >= 15) {
        results.push({
            json: {
                "Question_Category": quiz.Question_Category,
                "Question": question,
                "Answer": answer,
                "Additional_Info": quiz.Additional_Info || '',
                "queryQuestion": queryQuestion,
                "language": queryLanguage,
                "source": 'Online Quiz Info',
                "matchScore": matchScore,
                "matchedTerms": matchedTerms.slice(0, 6).join(' | ')
            }
        });
    }
}

// Sort by score
results.sort((a, b) => b.json.matchScore - a.json.matchScore);

