// Helper function to parse end date from duration string - MORE ROBUST
function parseEndDateFromDuration(durationStr) {
    if (!durationStr) return null;

    try {
        // Handle various formats:
        // "15 Nov-5 Dec", "15-Nov-5-Dec", "Nov 15-Dec 5", "15th Nov-5th Dec"
        // Remove "th", "st", "nd", "rd" from dates
        const cleanDuration = durationStr.replace(/(\d+)(st|nd|rd|th)/gi, '$1');

        // Try multiple regex patterns
        const patterns = [
            // Pattern 1: "15 Nov-5 Dec" or "15 Nov - 5 Dec"
            /(\d{1,2})\s*([A-Za-z]+)\s*[-–—]\s*(\d{1,2})\s*([A-Za-z]+)/,
            // Pattern 2: "Nov 15-Dec 5" or "Nov 15 - Dec 5"
            /([A-Za-z]+)\s*(\d{1,2})\s*[-–—]\s*([A-Za-z]+)\s*(\d{1,2})/
        ];

        for (let pattern of patterns) {
            const match = cleanDuration.match(pattern);
            if (match) {
                let endDay, endMonth;

                // Check which pattern matched
                if (pattern === patterns[0]) {
                    // Pattern 1: day month - day month
                    endDay = parseInt(match[3]);
                    endMonth = match[4];
                } else {
                    // Pattern 2: month day - month day
                    endMonth = match[3];
                    endDay = parseInt(match[4]);
                }

                // Month mapping
                const months = {
                    'jan': 0, 'january': 0,
                    'feb': 1, 'february': 1,
                    'mar': 2, 'march': 2,
                    'apr': 3, 'april': 3,
                    'may': 4,
                    'jun': 5, 'june': 5,
                    'jul': 6, 'july': 6,
                    'aug': 7, 'august': 7,
                    'sep': 8, 'sept': 8, 'september': 8,
                    'oct': 9, 'october': 9,
                    'nov': 10, 'november': 10,
                    'dec': 11, 'december': 11
                };

                const monthIndex = months[endMonth.toLowerCase()];
                if (monthIndex !== undefined && endDay) {
                    // Assume year 2025
                    const endDate = new Date(2025, monthIndex, endDay, 23, 59, 59, 999);
                    return endDate;
                }
            }
        }
    } catch (e) {
        return null;
    }

    return null;
}

// Helper function to check if event is over (ONLY returns "Already Over" or empty string)
function getEventStatus(event, language) {
    const t = templates[language] || templates.English;

    try {
        // Get current date/time
        const now = new Date();

        let eventEndDate = null;

        // CRITICAL: For multi-day events or events with date ranges, we MUST use end date
        if (event.Duration && typeof event.Duration === 'string') {
            // Check if Duration contains a date range (has hyphen/dash)
            if (event.Duration.includes('-') || event.Duration.includes('–') || event.Duration.includes('—')) {
                eventEndDate = parseEndDateFromDuration(event.Duration);
            }
        }

        // If we successfully parsed an end date from Duration, use it
        if (eventEndDate) {
            // Check if event is in the past
            if (now > eventEndDate) {
                return t.eventOver;
            } else {
                return ''; // Event is still ongoing or upcoming
            }
        }

        // If Duration parsing failed or no Duration range exists
        // For multi-day events, DON'T show status if we couldn't parse end date
        // This prevents false "Already Over" messages
        if (event.isMultiDay) {
            return ''; // Don't show status for multi-day events if we can't determine end date
        }

        // For single-day events, use the event Date
        eventEndDate = new Date(event.Date);

        // If time is provided, parse it
        if (event.Time && event.Time !== 'TBA') {
            let hours = 0;
            let minutes = 0;

            // Parse time
            const timeMatch = event.Time.match(/(\d{1,2}):(\d{2})/);
            if (timeMatch) {
                hours = parseInt(timeMatch[1]);
                minutes = parseInt(timeMatch[2]);

                // Handle AM/PM
                if (event.Time.toLowerCase().includes('pm') && hours !== 12) {
                    hours += 12;
                } else if (event.Time.toLowerCase().includes('am') && hours === 12) {
                    hours = 0;
                }
            }

            eventEndDate.setHours(hours, minutes, 0, 0);
        } else {
            // If no time specified, assume event ends at 11:59 PM
            eventEndDate.setHours(23, 59, 59, 999);
        }

        // Check if event is in the past
        if (now > eventEndDate) {
            return t.eventOver;
        } else {
            return '';
        }
    } catch (e) {
        // If any error occurs, don't show status (safe default)
        return '';
    }
}

// Helper function to extract base event name (remove day indicators)
function getBaseEventName(eventName) {
    if (!eventName) return '';

    return eventName
        .replace(/\s*[-–—]\s*(Day\s*\d+|दिवस\s*\d+|Opening|Closing|उद्घाटन|समापन|द्वितीय|तृतीय|प्रथम|चौथा|पांचवां)/gi, '')
        .replace(/\s*\(Day\s*\d+\)/gi, '')
        .replace(/\s*\(\d+\s*दिन\)/gi, '')
        .trim();
}

// Helper function to group related events (multi-day events)
function groupEvents(items, language) {
    const grouped = {};
    const standalone = [];

    for (const item of items) {
        const event = item.json;
        const eventNameEn = event.Event_Name_English || event.Event_Name || '';
        const eventNameHi = event.Event_Name_Hindi || event.Event_Name || '';

        const baseNameEn = getBaseEventName(eventNameEn);
        const baseNameHi = getBaseEventName(eventNameHi);
        const baseName = language === 'Hindi' ? baseNameHi : baseNameEn;

        const hasMultiDayIndicator = 
            eventNameEn.match(/Day\s*\d+|Opening|Closing|उद्घाटन|समापन|दिवस|प्रथम|द्वितीय|तृतीय/i) ||
            eventNameHi.match(/Day\s*\d+|Opening|Closing|उद्घाटन|समापन|दिवस|प्रथम|द्वितीय|तृतीय/i);

        if (hasMultiDayIndicator && baseName) {
            if (!grouped[baseName]) {
                grouped[baseName] = [];
            }
            grouped[baseName].push(item);
        } else {
            standalone.push(item);
        }
    }

    const mergedEvents = [];

    for (const [baseName, eventGroup] of Object.entries(grouped)) {
        if (eventGroup.length > 1) {
            mergedEvents.push(mergeMultiDayEvents(eventGroup, baseName, language));
        } else {
            standalone.push(eventGroup[0]);
        }
    }

    return [...mergedEvents, ...standalone];
}

// Helper function to merge multi-day events
function mergeMultiDayEvents(eventGroup, baseName, language) {
    eventGroup.sort((a, b) => {
        const dateA = new Date(a.json.Date || '2025-11-24');
        const dateB = new Date(b.json.Date || '2025-11-24');
        return dateA - dateB;
    });

    const firstEvent = eventGroup[0].json;
    const lastEvent = eventGroup[eventGroup.length - 1].json;

    const startDate = firstEvent.Date;
    const endDate = lastEvent.Date;
    const numDays = eventGroup.length;

    let mergedDescription = '';
    if (language === 'Hindi') {
        mergedDescription = numDays + ' दिवसीय कार्यक्रम। प्रमुख कार्यक्रम:\n';
    } else {
        mergedDescription = 'A ' + numDays + '-day event featuring:\n';
    }

    eventGroup.forEach((item, index) => {
        const event = item.json;
        const date = language === 'Hindi'
            ? (event.Date_Hindi || event.Date)
            : event.Date;
        const desc = language === 'Hindi'
            ? (event.Description_Hindi || event.Description)
            : (event.Description_English || event.Description);

        mergedDescription += '• Day ' + (index + 1) + ' (' + date + '): ' + desc + '\n';
    });

    const totalMatchScore = eventGroup.reduce((sum, item) => sum + (item.json.matchScore || 0), 0);

    return {
        json: {
            ...firstEvent,
            Event_Name: baseName,
            Event_Name_English: baseName,
            Event_Name_Hindi: baseName,
            Date: startDate,
            Duration: formatDateShort(startDate) + '-' + formatDateShort(endDate),
            Description: mergedDescription,
            Description_English: mergedDescription,
            Description_Hindi: mergedDescription,
            matchScore: totalMatchScore / eventGroup.length,
            isMultiDay: true,
            numDays: numDays,
            subEvents: eventGroup.map(item => ({
                date: item.json.Date,
                time: item.json.Time,
                name: item.json.Event_Name
            }))
        }
    };
}

function formatDateShort(dateStr) {
    if (!dateStr) return '';
    try {
        const date = new Date(dateStr);
        return date.toLocaleDateString('en-GB', { day: 'numeric', month: 'short' });
    } catch (e) {
        return dateStr;
    }
}

function formatDate(dateStr, dateHindi, language) {
    if (!dateStr) return 'TBA';

    if (language === 'Hindi' && dateHindi) {
        return dateHindi;
    }

    try {
        const date = new Date(dateStr);
        if (language === 'English') {
            return date.toLocaleDateString('en-US', { 
                weekday: 'short', 
                year: 'numeric', 
                month: 'short', 
                day: 'numeric' 
            });
        }
    } catch (e) {}

    return dateStr;
}

function formatTime(timeStr) {
    if (!timeStr) return 'TBA';

    if (timeStr.match(/^\d{2}:\d{2}$/)) {
        const [hours, minutes] = timeStr.split(':').map(Number);
        const period = hours >= 12 ? 'PM' : 'AM';
        const displayHours = hours > 12 ? hours - 12 : (hours === 0 ? 12 : hours);
        return displayHours + ':' + minutes.toString().padStart(2, '0') + ' ' + period;
    }

    return timeStr;
}

function getEventBadge(event, language) {
    const t = templates[language] || templates.English;

    if (event.isMultiDay) {
        return t.multiDayEvent.replace('{days}', event.numDays);
    }

    if (event.Duration === 'Daily') {
        return t.dailyEvent;
    }

    if (event.Event_Type && (event.Event_Type.includes('Special') || event.Event_Type.includes('Main'))) {
        return t.specialEvent;
    }

    return '';
}

// Check if we have results
if (!items || items.length === 0) {
    return [{
        json: {
            response: templates.English.notFound,
            success: false
        }
    }];
}

// Check if it's an error or "no match" response
const firstItem = items[0].json;
const userQuestion = firstItem.queryQuestion || firstItem.question || firstItem.searchedFor || "your question";

if (firstItem.error || firstItem.message) {
    const lang = firstItem.language || "English";
    const t = templates[lang] || templates.English;

    return [{
        json: {
            response: firstItem.message || firstItem.error || t.notFound,
            success: false,
            searchedFor: firstItem.searchedFor || userQuestion,
            suggestion: firstItem.suggestion || t.tryAgain,
            userQuestion: userQuestion,
            language: lang
        }
    }];
}

// Get the user's language
const language = firstItem.language || "English";
const t = templates[language] || templates.English;

// GROUP MULTI-DAY EVENTS
const processedItems = groupEvents(items, language);

// Build formatted response - start directly with events
let response = "";

// Format each event
processedItems.forEach((item, index) => {
    const event = item.json;

    const eventName = language === 'Hindi' 
        ? (event.Event_Name_Hindi || event.Event_Name)
        : (event.Event_Name_English || event.Event_Name);

    const venue = language === 'Hindi'
        ? (event.Venue_Hindi || event.Venue)
        : (event.Venue_English || event.Venue);

    const description = language === 'Hindi'
        ? (event.Description_Hindi || event.Description)
        : (event.Description_English || event.Description);

    const badge = getEventBadge(event, language);

    // Get event status (ONLY returns "Already Over" or empty string)
    const eventStatus = getEventStatus(event, language);

    // Simple event header
    response += (index + 1) + '. ' + eventName;
    if (badge) {
        response += ' ' + badge;
    }
    // Add event status ONLY if event is over
    if (eventStatus) {
        response += ' ' + eventStatus;
    }
    response += '\n\n';

    // Date and time
    if (event.isMultiDay) {
        response += t.duration + ': ' + event.Duration + ' (' + event.numDays + ' ' + t.days + ')\n';
        response += t.time + ': ' + formatTime(event.Time) + ' onwards\n';
    } else {
        const formattedDate = formatDate(event.Date, event.Date_Hindi, language);
        const formattedTime = formatTime(event.Time);
        response += t.date + ': ' + formattedDate + '\n';
        response += t.time + ': ' + formattedTime + '\n';

        if (event.Duration && event.Duration !== 'Daily' && event.Duration !== 'Main Day' && event.Duration !== 'Special Event') {
            response += t.duration + ': ' + event.Duration + '\n';
        }
    }

    // Venue
    response += t.venue + ': ' + venue + '\n';

    // Description
    if (description) {
        let desc = description;
        if (!event.isMultiDay && desc.length > 500) {
            desc = desc.substring(0, 500) + '...';
        }
        response += '\n' + desc + '\n';
    }

    // Separator between events
    if (index < processedItems.length - 1) {
        response += '\n' + '─'.repeat(30) + '\n\n';
    }
});

// Add website info at the end - Clickable link (NO template literals)
const website = 'http://internationalgitamahotsav.in';
const websiteText = language === 'Hindi' ? 'वेबसाइट देखें' : 'Visit Website';
response += '\n\n🌐 ' + websiteText + ': <a href="' + website + '" target="_blank" style="color: #1a73e8; text-decoration: underline;">' + website + '</a>';

// Return formatted response
return [{
    json: {
        response: response,
        success: true,
        totalResults: processedItems.length,
        originalResultsCount: items.length,
        groupedEvents: processedItems.length < items.length,
        userQuestion: userQuestion,
        language: language,
        events: processedItems.map(item => ({
            eventName: language === 'Hindi' 
                ? (item.json.Event_Name_Hindi || item.json.Event_Name)
                : (item.json.Event_Name_English || item.json.Event_Name),
            date: item.json.Date,
            time: item.json.Time,
            venue: language === 'Hindi'
                ? (item.json.Venue_Hindi || item.json.Venue)
                : (item.json.Venue_English || item.json.Venue),
            category: item.json.Category,
            intent: item.json.intent,
            matchScore: item.json.matchScore,
            source: item.json.source,
            duration: item.json.Duration,
            isMultiDay: item.json.isMultiDay || false
        }))
    }
}];

// Domain_Controller (AI-aware)

// Original query should already be present from earlier context
const originalQuery =
  $json.originalQuery ||
  $json.body?.query ||
  "";

// Extract AI response text
const aiContent =
  $json.choices?.[0]?.message?.content || "{}";

// Safe JSON parse
let aiResult = {};
try {
  aiResult = JSON.parse(aiContent);
} catch (e) {
  aiResult = {};
}

// Read values with fallback
const domain = aiResult.domain || "UNKNOWN";
const domainConfidence = aiResult.confidence || "Low";

return [
  {
    json: {
      originalQuery,
      language: "English",
      domain,
      domainConfidence
    }
  }
];

// -------- INPUT CONTEXT --------
const context = $input.first().json;

// Normalized query
const query = (context.normalizedQuery || "").toLowerCase();

// All sheet records coming via Merge node
const records = items.map(i => i.json);

// -------- SAFE STRING HELPER --------
function safeStr(v) {
  return (v || "").toString().toLowerCase();
}

// -------- SCORING FUNCTION --------
function computeScore(r) {
  let score = 0;

  const topic = safeStr(r.Topic_Name);
  const keywords = safeStr(r.Keywords);
  const evidenceType = safeStr(r.Evidence_Type);

  const words = query.split(/\s+/).filter(w => w.length > 2);

  // Strong topic match
  if (topic && query.includes(topic)) {
    score += 10;
  }

  // Keyword matching
  words.forEach(w => {
    if (keywords.includes(w)) score += 2;
  });

  // Archaeological query boost
  if (
    query.includes("archaeolog") &&
    evidenceType.includes("archaeolog")
  ) {
    score += 5;
  }

  // Methodology / limitation type boost
  if (
    (query.includes("why") ||
     query.includes("limitation") ||
     query.includes("method")) &&
    evidenceType.includes("method")
  ) {
    score += 5;
  }

  return score;
}

// -------- SCORE ALL RECORDS --------
const scored = records.map(r => ({
  ...r,
  matchScore: computeScore(r),
}));

// -------- SORT BEST FIRST --------
scored.sort((a, b) => b.matchScore - a.matchScore);

// -------- PICK TOP 3 --------
const matches = scored.slice(0, 3);

// -------- OUTPUT --------
return matches.map(r => ({
  json: {
    originalQuery: context.originalQuery,
    language: context.language,
    domain: context.domain,
    domainConfidence: context.domainConfidence,

    ...r,

    noRecordFound: r.matchScore === 0
  }
}));

const input = $input.first().json;

// Read from webhook body
const originalQuery = input.body?.query || "";
const language = input.body?.language || "English";
const categoryHint = input.body?.category || "";

// Normalize
const normalizedQuery = originalQuery.toLowerCase();

// Simple intent inference (can evolve later)
let intentType = "General";
if (
  normalizedQuery.includes("evidence") ||
  normalizedQuery.includes("research") ||
  normalizedQuery.includes("archaeological")
) {
  intentType = "Research";
}

return [
  {
    json: {
      originalQuery,
      normalizedQuery,
      language,
      intentType,
      categoryHint
    }
  }
];

// All matched DB records
const records = $input.all().map(i => i.json);

// Safety: if nothing came (should not happen here)
if (!records.length) {
  return [{
    json: {
      status: "NO_DATA",
      message: "No validated heritage records available."
    }
  }];
}

// 1️⃣ Sort by matchScore (highest first)
records.sort((a, b) => (b.matchScore || 0) - (a.matchScore || 0));

// 2️⃣ Primary record
const primary = records[0];

// 3️⃣ Supporting records (max 2, clearly secondary)
const supporting = records.slice(1, 3).map(r => ({
  topic: r.Topic_Name,
  evidenceStatus: r.Evidence_Status,
  evidenceType: r.Evidence_Type,
  notes: r.Evidence_Notes
}));

// 4️⃣ Final composed response
return [{
  json: {
    originalQuery: primary.originalQuery,
    domain: primary.domain,
    intentType: primary.intentType,

    primaryFinding: {
      topic: primary.Topic_Name,
      evidenceStatus: primary.Evidence_Status,
      evidenceType: primary.Evidence_Type,
      literaryReference: primary.Literary_Reference,
      sourceAuthority: primary.Source_Authority,
      confidenceLevel: primary.Confidence_Level,
      periodAssociated: primary.Period_Associated,
      evidenceNotes: primary.Evidence_Notes
    },

    supportingContext: supporting,

    responseType: "DB_VALIDATED",
    confidenceIndicator: "High confidence (DB validated)",
    disclaimer: "This response is generated strictly from curated heritage research records. Absence of archaeological evidence does not imply historical negation."
  }
}];

