// ---- Helper: Markdown **bold** → HTML <b> ----
function mdToHtmlBold(text) {
  if (!text) return "";
  return text.replace(/\*\*(.*?)\*\*/g, "<b>$1</b>");
}

const type = $json.responseType || "DB_VALIDATED";

if (type === "DOMAIN_REDIRECT") {
  return [
    {
      json: {
        originalQuery: $json.originalQuery,
        formattedAnswer: `<b>Notice:</b><br>${$json.researchOutput}`,
        disclaimer: ""
      }
    }
  ];
}


const input = $input.first().json;

// ---- Basic fields ----
const question = input.originalQuery || "";
const finding = input.primaryFinding || {};
const context = input.supportingContext || [];
const disclaimer = input.disclaimer || "";

// ---- Build Findings Section ----
let answer = "";

answer += `**Topic:** ${finding.topic || "Not Available"}\n\n`;

answer += `**Evidence Status:** ${finding.evidenceStatus || "Not Available"}\n`;
answer += `• Evidence Type: ${finding.evidenceType || "Not Available"}\n`;
answer += `• Literary Reference: ${finding.literaryReference || "Not Available"}\n`;
answer += `• Source Authority: ${finding.sourceAuthority || "Not Available"}\n\n`;

answer += `**Notes:**\n${finding.evidenceNotes || "Not Available"}\n\n`;

answer += `**Period:** ${finding.periodAssociated || "Unknown"}\n\n`;

// ---- Supporting Context ----
if (context.length > 0) {
  answer += `**Additional Context:**\n`;

  context.forEach(c => {
    answer += `• ${c.topic}: ${c.notes}\n`;
  });

  answer += "\n";
}

// ---- Disclaimer ----
if (disclaimer) {
  answer += `---\n**Disclaimer:** ${disclaimer}`;
}

// ---- Convert Markdown bold to HTML ----
answer = mdToHtmlBold(answer);

// ---- Final Output ----
return [
  {
    json: {
      question,
      formattedAnswer: answer,
      responseType: input.responseType || "DB_VALIDATED"
    }
  }
];

